CREATE TABLE "ProductSpace" ("id" TEXT NOT NULL PRIMARY KEY,"name" TEXT NOT NULL,"createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "Project" ("id" TEXT NOT NULL PRIMARY KEY,"productSpaceId" TEXT NOT NULL,"key" TEXT NOT NULL,"name" TEXT NOT NULL,"createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "Project_productSpaceId_fkey" FOREIGN KEY ("productSpaceId") REFERENCES "ProductSpace"("id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE TABLE "Release" ("id" TEXT NOT NULL PRIMARY KEY,"productSpaceId" TEXT NOT NULL,"projectId" TEXT NOT NULL,"name" TEXT NOT NULL,"version" TEXT,"description" TEXT,"status" TEXT NOT NULL DEFAULT 'DRAFT',"owner" TEXT,"startDate" DATETIME,"targetDate" DATETIME,"archivedAt" DATETIME,"createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" DATETIME NOT NULL,CONSTRAINT "Release_projectId_fkey" FOREIGN KEY ("projectId") REFERENCES "Project"("id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE TABLE "Feature" ("id" TEXT NOT NULL PRIMARY KEY,"productSpaceId" TEXT NOT NULL,"projectId" TEXT NOT NULL,"releaseId" TEXT,"key" TEXT NOT NULL,"title" TEXT NOT NULL,"description" TEXT NOT NULL DEFAULT '',"problemStatement" TEXT NOT NULL DEFAULT '',"businessValue" TEXT NOT NULL DEFAULT '',"functionalRequirements" TEXT NOT NULL DEFAULT '[]',"nonFunctionalRequirements" TEXT NOT NULL DEFAULT '[]',"dependencies" TEXT NOT NULL DEFAULT '[]',"risks" TEXT NOT NULL DEFAULT '[]',"assumptions" TEXT NOT NULL DEFAULT '[]',"status" TEXT NOT NULL DEFAULT 'DRAFT',"priority" TEXT NOT NULL DEFAULT 'MEDIUM',"owner" TEXT,"source" TEXT NOT NULL DEFAULT 'AI',"aiGenerationId" TEXT,"archivedAt" DATETIME,"createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" DATETIME NOT NULL,FOREIGN KEY("projectId") REFERENCES "Project"("id"),FOREIGN KEY("releaseId") REFERENCES "Release"("id") ON DELETE SET NULL,FOREIGN KEY("aiGenerationId") REFERENCES "AiGeneration"("id") ON DELETE SET NULL);
CREATE TABLE "UserStory" ("id" TEXT NOT NULL PRIMARY KEY,"productSpaceId" TEXT NOT NULL,"projectId" TEXT NOT NULL,"featureId" TEXT NOT NULL,"releaseId" TEXT,"key" TEXT NOT NULL,"title" TEXT NOT NULL,"persona" TEXT NOT NULL DEFAULT '',"goal" TEXT NOT NULL DEFAULT '',"benefit" TEXT NOT NULL DEFAULT '',"description" TEXT NOT NULL DEFAULT '',"status" TEXT NOT NULL DEFAULT 'DRAFT',"priority" TEXT NOT NULL DEFAULT 'MEDIUM',"storyPoints" INTEGER,"assignee" TEXT,"sprintId" TEXT,"source" TEXT NOT NULL DEFAULT 'AI',"aiGenerationId" TEXT,"archivedAt" DATETIME,"createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" DATETIME NOT NULL,FOREIGN KEY("projectId") REFERENCES "Project"("id"),FOREIGN KEY("featureId") REFERENCES "Feature"("id") ON DELETE RESTRICT,FOREIGN KEY("releaseId") REFERENCES "Release"("id") ON DELETE SET NULL);
CREATE TABLE "AcceptanceCriterion" ("id" TEXT NOT NULL PRIMARY KEY,"featureId" TEXT,"userStoryId" TEXT,"givenText" TEXT,"whenText" TEXT,"thenText" TEXT,"criteriaText" TEXT,"sortOrder" INTEGER NOT NULL DEFAULT 0,"completed" BOOLEAN NOT NULL DEFAULT false,"createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" DATETIME NOT NULL,FOREIGN KEY("featureId") REFERENCES "Feature"("id") ON DELETE CASCADE,FOREIGN KEY("userStoryId") REFERENCES "UserStory"("id") ON DELETE CASCADE);
CREATE TABLE "AiGeneration" ("id" TEXT NOT NULL PRIMARY KEY,"productSpaceId" TEXT NOT NULL,"projectId" TEXT NOT NULL,"releaseId" TEXT,"featureId" TEXT,"generationType" TEXT NOT NULL,"inputText" TEXT NOT NULL DEFAULT '',"sourceSnapshot" TEXT NOT NULL DEFAULT '{}',"generatedContent" TEXT NOT NULL,"provider" TEXT NOT NULL DEFAULT 'DETERMINISTIC_DEMO',"model" TEXT NOT NULL DEFAULT 'local',"status" TEXT NOT NULL DEFAULT 'GENERATED',"createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,"savedAt" DATETIME,FOREIGN KEY("projectId") REFERENCES "Project"("id"),FOREIGN KEY("releaseId") REFERENCES "Release"("id") ON DELETE SET NULL);
CREATE UNIQUE INDEX "Project_key_key" ON "Project"("key");CREATE INDEX "Release_projectId_idx" ON "Release"("projectId");CREATE UNIQUE INDEX "Feature_key_key" ON "Feature"("key");CREATE UNIQUE INDEX "Feature_aiGenerationId_key" ON "Feature"("aiGenerationId");CREATE INDEX "Feature_projectId_idx" ON "Feature"("projectId");CREATE INDEX "Feature_releaseId_idx" ON "Feature"("releaseId");CREATE UNIQUE INDEX "UserStory_key_key" ON "UserStory"("key");CREATE INDEX "UserStory_featureId_idx" ON "UserStory"("featureId");CREATE INDEX "UserStory_projectId_idx" ON "UserStory"("projectId");CREATE INDEX "UserStory_releaseId_idx" ON "UserStory"("releaseId");CREATE INDEX "AiGeneration_featureId_idx" ON "AiGeneration"("featureId");
